CREATE TABLE IF NOT EXISTS centers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,kind VARCHAR(20) NOT NULL DEFAULT 'clinic',license_number VARCHAR(40) NOT NULL UNIQUE,national_id VARCHAR(11) NULL,manager_name VARCHAR(190) NOT NULL,technical_manager VARCHAR(190) NOT NULL DEFAULT '',technical_code VARCHAR(30) NOT NULL DEFAULT '',city_id INT UNSIGNED NOT NULL,address TEXT NOT NULL,phone VARCHAR(20) NOT NULL,latitude DECIMAL(9,6) NULL,longitude DECIMAL(9,6) NULL,description TEXT NULL,logo_file VARCHAR(80) NULL,document_file VARCHAR(80) NULL,owner_user_id BIGINT UNSIGNED NOT NULL,review_status VARCHAR(20) NOT NULL DEFAULT 'pending',review_note TEXT NULL,active TINYINT NOT NULL DEFAULT 1,subscription_until DATE NULL,trial_used_at DATETIME NULL,status_changed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX center_status(review_status,active),INDEX center_city(city_id),FOREIGN KEY(city_id) REFERENCES cities(id),FOREIGN KEY(owner_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS center_branches(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,center_id INT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,city_id INT UNSIGNED NOT NULL,address TEXT NOT NULL,phone VARCHAR(20) NOT NULL DEFAULT '',latitude DECIMAL(9,6) NULL,longitude DECIMAL(9,6) NULL,is_main TINYINT NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX branch_center(center_id,active),FOREIGN KEY(center_id) REFERENCES centers(id),FOREIGN KEY(city_id) REFERENCES cities(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS center_rooms(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,branch_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,note VARCHAR(255) NOT NULL DEFAULT '',active TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY room_name(branch_id,name),FOREIGN KEY(branch_id) REFERENCES center_branches(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS center_doctors(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,center_id INT UNSIGNED NOT NULL,doctor_id BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'invited',initiated_by VARCHAR(10) NOT NULL DEFAULT 'center',perm_schedule TINYINT NOT NULL DEFAULT 0,perm_bookings TINYINT NOT NULL DEFAULT 0,perm_history TINYINT NOT NULL DEFAULT 0,perm_reports TINYINT NOT NULL DEFAULT 1,message VARCHAR(500) NOT NULL DEFAULT '',created_by_user BIGINT UNSIGNED NULL,responded_at DATETIME NULL,ended_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY center_doctor(center_id,doctor_id),INDEX link_doctor(doctor_id,status),FOREIGN KEY(center_id) REFERENCES centers(id),FOREIGN KEY(doctor_id) REFERENCES doctors(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS center_staff(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,center_id INT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'staff',branch_id BIGINT UNSIGNED NULL,perm_center TINYINT NOT NULL DEFAULT 0,perm_doctors TINYINT NOT NULL DEFAULT 0,perm_staff TINYINT NOT NULL DEFAULT 0,perm_schedule TINYINT NOT NULL DEFAULT 0,perm_bookings TINYINT NOT NULL DEFAULT 0,perm_history TINYINT NOT NULL DEFAULT 0,perm_reports TINYINT NOT NULL DEFAULT 0,perm_announce TINYINT NOT NULL DEFAULT 0,perm_billing TINYINT NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY center_user(center_id,user_id),INDEX staff_user(user_id,active),FOREIGN KEY(center_id) REFERENCES centers(id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(branch_id) REFERENCES center_branches(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS center_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,number VARCHAR(30) NULL UNIQUE,center_id INT UNSIGNED NOT NULL,plan_id INT UNSIGNED NOT NULL,plan_name VARCHAR(120) NOT NULL,duration_days SMALLINT UNSIGNED NOT NULL,base_toman INT UNSIGNED NOT NULL,discount_code_id INT UNSIGNED NULL,discount_toman INT UNSIGNED NOT NULL DEFAULT 0,vat_percent DECIMAL(5,2) NOT NULL DEFAULT 0,vat_toman INT UNSIGNED NOT NULL DEFAULT 0,payable_toman INT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'proforma',payment_method VARCHAR(20) NULL,payment_tx_id BIGINT UNSIGNED NULL,offline_reference VARCHAR(100) NULL,period_start DATE NULL,period_end DATE NULL,expires_at DATETIME NOT NULL,created_by_user BIGINT UNSIGNED NULL,created_by_admin BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,paid_at DATETIME NULL,INDEX corder_center(center_id,status),INDEX corder_paid(status,paid_at),FOREIGN KEY(center_id) REFERENCES centers(id),FOREIGN KEY(plan_id) REFERENCES subscription_plans(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS center_subscriptions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,center_id INT UNSIGNED NOT NULL,starts_on DATE NOT NULL,ends_on DATE NOT NULL,kind VARCHAR(20) NOT NULL,order_id BIGINT UNSIGNED NULL,amount_toman INT UNSIGNED NOT NULL DEFAULT 0,days SMALLINT UNSIGNED NULL,note VARCHAR(255) NOT NULL DEFAULT '',created_by_admin BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX csub_center(center_id,starts_on,ends_on),FOREIGN KEY(center_id) REFERENCES centers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS center_announcements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,center_id INT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NULL,doctor_id BIGINT UNSIGNED NULL,date_from DATE NOT NULL,date_to DATE NOT NULL,title VARCHAR(190) NOT NULL,body TEXT NOT NULL,send_sms TINYINT NOT NULL DEFAULT 0,recipients INT UNSIGNED NOT NULL DEFAULT 0,sms_queued INT UNSIGNED NOT NULL DEFAULT 0,created_by_user BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX ann_center(center_id,id),FOREIGN KEY(center_id) REFERENCES centers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS center_announcement_recipients(announcement_id BIGINT UNSIGNED NOT NULL,booking_id BIGINT UNSIGNED NOT NULL,channel VARCHAR(10) NOT NULL,PRIMARY KEY(announcement_id,booking_id,channel),FOREIGN KEY(announcement_id) REFERENCES center_announcements(id),FOREIGN KEY(booking_id) REFERENCES bookings(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS center_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,center_id INT UNSIGNED NOT NULL,actor_user_id BIGINT UNSIGNED NULL,actor_admin_id BIGINT UNSIGNED NULL,event_type VARCHAR(80) NOT NULL,details TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX cevent_center(center_id,id),FOREIGN KEY(center_id) REFERENCES centers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
